 const g=model.goalDiagnosis||{},goal=base.goal;
 const goalActionIds=new Set(materials.goalActions.map(a=>a.id));
 const goalPlans=(Array.isArray(g.plans)?g.plans:[]).filter(p=>clean(p.title)&&clean(p.detail)&&clean(p.verification)&&goalActionIds.has(p.actionId));
 if(goalMode&&goal?.target>0&&(!clean(g.judgment)||!clean(g.basis)||!clean(g.uncertainty)||!goalPlans.length))errors.push('目标诊断的模型判断、依据或行动不完整');
 const goalDiagnosis=goalMode&&goal?.target>0?{judgment:clean(g.judgment),basis:clean(g.basis),uncertainty:clean(g.uncertainty),plans:goalPlans}:undefined;
 const status=errors.length?'partial':base.status;
 const answer=issueOnly?findings.map(f=>f.explanation).filter(Boolean).join('；'):clean(model.summary)||base.answer;
 return {...base,status,diagnosis:findings,goalDiagnosis,answer:summaryErrors.length?'本次综合经营小结尚未完整核验，请重新诊断。':answer,missing:[...new Set([...(base.missing||[]),...errors])],quality:{validated:errors.length===0,errors},workflow:{contract:1,revision:'diagnosis-v3-scene-output',explanationOrigin:'model_node',modelOutputReceived:typeof model.summary==='string'&&Array.isArray(model.explanations),validated:errors.length===0}};
}

async function businessMain({params}: Args): Promise<Output> { const model=params;const result=finalizeWorkflowDiagnosis(JSON.parse(params.calculationJson),model);return {result,passed:result.quality.validated,validationErrors:result.quality.errors.join('；')}; }
function parseModelUsageRecords(value) {
 if (value == null || value === '') return [];
 if (typeof value === 'string') return parseModelUsageRecords(JSON.parse(value));
 if (Array.isArray(value)) return value.flatMap(parseModelUsageRecords);
 if (!value || typeof value !== 'object') throw new Error('模型用量格式无效');
 const stages = ['understanding', 'explanation', 'repair', 'knowledge'];
 if (!stages.includes(value.stage)) throw new Error('模型用量缺少调用阶段');
 const fields = ['inputTokens', 'outputTokens', 'totalTokens', 'cachedInputTokens', 'reasoningTokens'];
 const available = fields.every(key => Number.isSafeInteger(value[key]) && value[key] >= 0)
  && value.inputTokens + value.outputTokens === value.totalTokens
  && value.cachedInputTokens <= value.inputTokens
  && value.reasoningTokens <= value.outputTokens;
 return [{stage: value.stage, available,
  ...(typeof value.responseId === 'string' ? {responseId: value.responseId} : {}),
  ...(typeof value.model === 'string' ? {model: value.model} : {}),
  ...(['none', 'low', 'high'].includes(value.reasoningEffort) ? {reasoningEffort: value.reasoningEffort} : {}),
  ...(available ? Object.fromEntries(fields.map(key => [key, value[key]])) : {})}];
}
async function main({params}: Args): Promise<Output> {
 const result=await businessMain({params});
 return {...result,usageJson:JSON.stringify(parseModelUsageRecords([params.previousUsageJson,params.usageJson || {stage:'repair',available:false}]))};
}

